<h2 class="mb-3">Combo</h2><div class="alert alert-info">Combo dùng chung cho FPS và Couple. Khoảng 12:00–17:00 dùng giá giờ thường.</div><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Tên combo</th><th>Khung giờ</th><th>Giá</th><th>Nhóm máy</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach ($combos as $combo): ?><tr><td><?= htmlspecialchars((string) $combo['name']) ?></td><td><?= htmlspecialchars(substr((string) $combo['starts_at'], 0, 5)) ?> – <?= htmlspecialchars(substr((string) $combo['ends_at'], 0, 5)) ?><?= ((int) ($combo['crosses_midnight'] ?? 0) === 1) ? ' (qua đêm)' : '' ?></td><td><?= number_format((float) $combo['price'], 0, ',', '.') ?> đ</td><td><?= htmlspecialchars((string) $combo['machine_group']) ?></td><td><?= htmlspecialchars((string) $combo['status']) ?></td><td><form method="post" action="<?= htmlspecialchars(BASE_URL . '/combos/toggle') ?>"><input type="hidden" name="id" value="<?= (int) $combo['id'] ?>"><button class="btn btn-sm btn-outline-secondary">Bật/tắt</button></form></td></tr><?php endforeach; ?></tbody></table></div>
